def _verify(headers, body, secrets, now):
    h = {str(k).lower(): v for k, v in headers.items()}
    sig = h.get("corvid-signature")
    event_id = h.get("corvid-event-id")
    if not isinstance(sig, str) or not isinstance(event_id, str) or not sig.strip():
        return False
    ts = []
    v2 = []
    for el in sig.split(","):
        el = el.lstrip(" ")
        key, sep, val = el.partition("=")
        if not sep or not key:
            return False
        if key == "t":
            ts.append(val)
        elif key == "v2":
            v2.append(val)
    if len(ts) != 1 or not (ts[0].isascii() and ts[0].isdigit()):
        return False
    t = int(ts[0])
    if t < now - 300 or t > now + 60:
        return False
    payload = b"v2:" + ts[0].encode() + b":" + event_id.encode() + b":" + bytes(body)
    ok = False
    for secret in secrets:
        if not secret.startswith("whsec_"):
            continue
        try:
            key = base64.b64decode(secret[6:], validate=True)
        except Exception:
            continue
        exp = hmac.new(key, payload, hashlib.sha256).hexdigest()
        for cand in v2:
            if len(cand) == 64 and hmac.compare_digest(cand.encode(), exp.encode()):
                ok = True
    return ok''')
